//! Human-only key, governance configuration and append-only CNY/USD exchange-rate publication.
//! Key material is generated by Web Crypto; only its SHA-256 digest crosses this boundary.
use crate::{
    console::Permission,
    error::{Error, Result},
    governance::{self, Tx},
    human::Human,
    money,
};
use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use serde_json::{Value, json};
use sqlx::PgPool;
use uuid::Uuid;

pub(crate) async fn begin(
    pool: &PgPool,
    who: &Human,
    read: Permission,
    write: Option<Permission>,
) -> Result<Tx<'static>> {
    let mut tx = pool.begin().await?;
    sqlx::query("SET LOCAL statement_timeout='5s'")
        .execute(&mut *tx)
        .await?;
    sqlx::query("SET LOCAL lock_timeout='1s'")
        .execute(&mut *tx)
        .await?;
    // Same tenant -> key order as accounting. Never upgrade a shared tenant lock.
    let tenant = if write.is_some() {
        "SELECT active FROM tenants WHERE id=$1 FOR UPDATE"
    } else {
        "SELECT active FROM tenants WHERE id=$1 FOR SHARE"
    };
    if sqlx::query_scalar::<_, bool>(tenant)
        .bind(who.tenant_id)
        .fetch_optional(&mut *tx)
        .await?
        != Some(true)
    {
        return Err(Error::ConsoleForbidden);
    }
    if sqlx::query_scalar::<_, bool>(
        "SELECT active FROM governance_users WHERE tenant_id=$1 AND id=$2 FOR SHARE",
    )
    .bind(who.tenant_id)
    .bind(who.id)
    .fetch_optional(&mut *tx)
    .await?
        != Some(true)
    {
        return Err(Error::ConsoleForbidden);
    }
    let grants: Vec<String> = sqlx::query_scalar("SELECT permission FROM console_permissions WHERE tenant_id=$1 AND user_id=$2 AND (permission=$3 OR permission=$4) AND enabled ORDER BY permission FOR SHARE")
        .bind(who.tenant_id).bind(who.id).bind(read.name()).bind(write.map(Permission::name)).fetch_all(&mut *tx).await?;
    if grants.len() != if write.is_some() { 2 } else { 1 } {
        return Err(Error::ConsoleForbidden);
    }
    fresh(&mut tx, who).await?;
    Ok(tx)
}
async fn fresh(tx: &mut Tx<'_>, who: &Human) -> Result<()> {
    let valid: bool =
        sqlx::query_scalar("SELECT clock_timestamp()<to_timestamp($1::double precision)")
            .bind(who.expires_at() as f64)
            .fetch_one(&mut **tx)
            .await?;
    if !valid {
        return Err(Error::HumanUnauthorized);
    }
    Ok(())
}
pub(crate) async fn finish(mut tx: Tx<'_>, who: &Human, result: Value) -> Result<Value> {
    fresh(&mut tx, who).await?;
    tx.commit().await?;
    Ok(result)
}
pub(crate) async fn can_write(tx: &mut Tx<'_>, who: &Human, p: Permission) -> Result<bool> {
    Ok(sqlx::query_scalar("SELECT EXISTS(SELECT 1 FROM console_permissions WHERE tenant_id=$1 AND user_id=$2 AND permission=$3 AND enabled)")
        .bind(who.tenant_id).bind(who.id).bind(p.name()).fetch_one(&mut **tx).await?)
}
fn text(v: &str) -> Result<()> {
    if !governance::valid_text(v, 200) {
        return Err(Error::Invalid("invalid configuration text"));
    }
    Ok(())
}
pub(crate) fn revision(v: &str) -> Result<i64> {
    let n = v
        .parse::<i64>()
        .map_err(|_| Error::Invalid("invalid revision"))?;
    if n <= 0 || n.to_string() != v {
        return Err(Error::Invalid("invalid revision"));
    }
    Ok(n)
}
fn page(limit: i64) -> Result<()> {
    if !(1..=100).contains(&limit) {
        return Err(Error::Invalid("invalid page size"));
    }
    Ok(())
}
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub struct KeyQuery {
    pub after: Option<Uuid>,
    pub search: Option<String>,
    pub limit: i64,
}
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub struct KeyDetail {
    pub id: Uuid,
}
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub struct FxQuery {
    pub before: Option<String>,
    pub limit: i64,
}

pub async fn keys(pool: &PgPool, who: &Human, q: KeyQuery) -> Result<Value> {
    page(q.limit)?;
    if let Some(s) = &q.search {
        text(s)?;
    }
    let mut tx = begin(pool, who, Permission::KeysRead, None).await?;
    let mut rows:Vec<Value>=sqlx::query_scalar("SELECT jsonb_build_object('id',id,'name',name,'prefix',key_prefix,'revision',config_revision::text,'budget_cny',(budget_micros::numeric*0.000001)::text,'spent_cny',(spent_micros::numeric*0.000001)::text,'reserved_cny',(reserved_micros::numeric*0.000001)::text,'expires_at',expires_at,'revoked_at',revoked_at,'created_at',created_at) FROM virtual_keys WHERE tenant_id=$1 AND ($2::uuid IS NULL OR id>$2) AND ($3::text IS NULL OR strpos(lower(name),lower($3))>0 OR id::text=$3 OR key_prefix=$3) ORDER BY id LIMIT $4")
        .bind(who.tenant_id).bind(q.after).bind(q.search).bind(q.limit+1).fetch_all(&mut *tx).await?;
    let more = rows.len() > q.limit as usize;
    rows.truncate(q.limit as usize);
    let next = if more {
        rows.last().map(|r| r["id"].clone())
    } else {
        None
    };
    let tenant:Value=sqlx::query_scalar("SELECT jsonb_build_object('budget_cny',(budget_micros::numeric*0.000001)::text,'spent_cny',(spent_micros::numeric*0.000001)::text,'reserved_cny',(reserved_micros::numeric*0.000001)::text) FROM tenants WHERE id=$1")
        .bind(who.tenant_id).fetch_one(&mut *tx).await?;
    let result = json!({"currency":"CNY","data":rows,"next_after":next,"tenant":tenant,"can_write":can_write(&mut tx,who,Permission::KeysWrite).await?});
    finish(tx, who, result).await
}
pub async fn key_detail(pool: &PgPool, who: &Human, q: KeyDetail) -> Result<Value> {
    let mut tx = begin(pool, who, Permission::KeysRead, None).await?;
    let row:Value=sqlx::query_scalar("SELECT jsonb_build_object('id',id,'name',name,'prefix',key_prefix,'revision',config_revision::text,'budget_cny',(budget_micros::numeric*0.000001)::text,'spent_cny',(spent_micros::numeric*0.000001)::text,'reserved_cny',(reserved_micros::numeric*0.000001)::text,'expires_at',expires_at,'revoked_at',revoked_at,'created_at',created_at) FROM virtual_keys WHERE tenant_id=$1 AND id=$2 FOR SHARE")
        .bind(who.tenant_id).bind(q.id).fetch_optional(&mut *tx).await?.ok_or(Error::NotFound)?;
    let mut models:Vec<String>=sqlx::query_scalar("SELECT model_id FROM key_models WHERE tenant_id=$1 AND key_id=$2 ORDER BY model_id LIMIT 101")
        .bind(who.tenant_id).bind(q.id).fetch_all(&mut *tx).await?;
    let truncated = models.len() > 100;
    models.truncate(100);
    let result = json!({"key":row,"models":models,"grants_truncated":truncated,"can_write":can_write(&mut tx,who,Permission::KeysWrite).await?});
    finish(tx, who, result).await
}
// Key administrators can discover grant targets without receiving endpoint or provider configuration.
pub async fn models(pool: &PgPool, who: &Human, q: crate::catalog::ModelQuery) -> Result<Value> {
    page(q.limit)?;
    for s in [&q.after, &q.search].into_iter().flatten() {
        text(s)?;
    }
    let mut tx = begin(pool, who, Permission::KeysRead, None).await?;
    let mut rows:Vec<Value>=sqlx::query_scalar("SELECT jsonb_build_object('id',id,'name',name,'active',active) FROM models WHERE tenant_id=$1 AND ($2::text IS NULL OR id>$2) AND ($3::text IS NULL OR strpos(lower(id),lower($3))>0 OR strpos(lower(name),lower($3))>0) ORDER BY id LIMIT $4")
        .bind(who.tenant_id).bind(q.after).bind(q.search).bind(q.limit+1).fetch_all(&mut *tx).await?;
    let more = rows.len() > q.limit as usize;
    rows.truncate(q.limit as usize);
    let next = if more {
        rows.last().map(|r| r["id"].clone())
    } else {
        None
    };
    finish(tx, who, json!({"data":rows,"next_after":next})).await
}
pub async fn fx(pool: &PgPool, who: &Human, q: FxQuery) -> Result<Value> {
    page(q.limit)?;
    let before = q.before.as_deref().map(revision).transpose()?;
    let mut tx = begin(pool, who, Permission::FxRead, None).await?;
    let mut result:Value=sqlx::query_scalar("SELECT jsonb_build_object('currency','CNY','observed_at',statement_timestamp(),'latest_id',(SELECT max(id)::text FROM fx_rates WHERE tenant_id=$1),'current',(SELECT jsonb_build_object('id',id::text,'usd_cny',usd_cny::text,'source',source,'effective_at',effective_at) FROM fx_rates WHERE tenant_id=$1 AND effective_at<=statement_timestamp() ORDER BY effective_at DESC LIMIT 1),'data',COALESCE((SELECT jsonb_agg(r.v ORDER BY r.id DESC) FROM (SELECT id,jsonb_build_object('id',id::text,'usd_cny',usd_cny::text,'source',source,'effective_at',effective_at) AS v FROM fx_rates WHERE tenant_id=$1 AND ($2::bigint IS NULL OR id<$2) ORDER BY id DESC LIMIT $3) r),'[]'::jsonb))")
        .bind(who.tenant_id).bind(before).bind(q.limit+1).fetch_one(&mut *tx).await?;
    let rows = result["data"].as_array_mut().ok_or(Error::Configuration)?;
    let more = rows.len() > q.limit as usize;
    rows.truncate(q.limit as usize);
    let next = if more {
        rows.last().map(|r| r["id"].clone())
    } else {
        None
    };
    result["next_before"] = json!(next);
    result["can_write"] = json!(can_write(&mut tx, who, Permission::FxWrite).await?);
    finish(tx, who, result).await
}

#[derive(Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Mutation {
    pub operation_id: Uuid,
    pub reason: String,
    pub change: Change,
}
#[derive(Deserialize, Serialize)]
#[serde(tag = "kind", rename_all = "snake_case", deny_unknown_fields)]
pub enum Change {
    GuardrailPublish {
        id: String,
        expected_revision: Option<String>,
        name: String,
        stage: String,
        rule: Value,
        active: bool,
    },
    PolicyPut {
        id: Uuid,
        expected_revision: Option<String>,
        guardrail_id: String,
        model_id: Option<String>,
        key_id: Option<Uuid>,
        runtime_id: Option<String>,
        tool_name: Option<String>,
        active: bool,
    },
    KeyCreate {
        name: String,
        key_hash: String,
        key_prefix: String,
        budget_cny: String,
        models: Vec<String>,
        expires_at: DateTime<Utc>,
    },
    KeyUpdate {
        id: Uuid,
        expected_revision: String,
        name: String,
        budget_cny: String,
        models: Vec<String>,
        expires_at: Option<DateTime<Utc>>,
    },
    KeyRevoke {
        id: Uuid,
        expected_revision: String,
    },
    FxPublish {
        expected_latest_id: Option<String>,
        usd_cny: String,
        source: String,
        effective_at: Option<DateTime<Utc>>,
    },
}
async fn validate_key(
    tx: &mut Tx<'_>,
    who: &Human,
    name: &str,
    budget: &str,
    models: &[String],
    expires: Option<DateTime<Utc>>,
) -> Result<i64> {
    text(name)?;
    if expires.is_some_and(|e| e.timestamp_subsec_nanos() % 1000 != 0) {
        return Err(Error::Invalid(
            "expiry supports at most microsecond precision",
        ));
    }
    let budget = money::cny_micros(budget)?;
    if models.is_empty() || models.len() > 100 {
        return Err(Error::Invalid("one to 100 explicit model grants required"));
    }
    let mut seen = std::collections::HashSet::new();
    for m in models {
        text(m)?;
        if !seen.insert(m) {
            return Err(Error::Invalid("duplicate model grant"));
        }
    }
    let valid:bool=sqlx::query_scalar("SELECT budget_micros>=$2 AND ($3::timestamptz IS NULL OR ($3>clock_timestamp() AND $3<=clock_timestamp()+interval '366 days')) FROM tenants WHERE id=$1")
        .bind(who.tenant_id).bind(budget).bind(expires).fetch_one(&mut **tx).await?;
    if !valid {
        return Err(Error::Invalid(
            "key budget exceeds tenant ceiling or expiry outside next 366 days",
        ));
    }
    let known: i64 =
        sqlx::query_scalar("SELECT count(*) FROM models WHERE tenant_id=$1 AND id=ANY($2)")
            .bind(who.tenant_id)
            .bind(models)
            .fetch_one(&mut **tx)
            .await?;
    if known != models.len() as i64 {
        return Err(Error::Invalid("unknown model grant"));
    }
    Ok(budget)
}
async fn replace_grants(tx: &mut Tx<'_>, tenant: Uuid, id: Uuid, models: &[String]) -> Result<()> {
    sqlx::query(
        "DELETE FROM key_models WHERE tenant_id=$1 AND key_id=$2 AND NOT(model_id=ANY($3))",
    )
    .bind(tenant)
    .bind(id)
    .bind(models)
    .execute(&mut **tx)
    .await?;
    sqlx::query("INSERT INTO key_models(tenant_id,key_id,model_id) SELECT $1,$2,unnest($3::text[]) ON CONFLICT DO NOTHING").bind(tenant).bind(id).bind(models).execute(&mut **tx).await?;
    Ok(())
}
async fn key_before(tx: &mut Tx<'_>, tenant: Uuid, id: Uuid, expected: &str) -> Result<Value> {
    let (version,row):(i64,Value)=sqlx::query_as("SELECT config_revision,jsonb_build_object('name',name,'budget_cny',(budget_micros::numeric*0.000001)::text,'expires_at',expires_at,'revoked_at',revoked_at) FROM virtual_keys WHERE tenant_id=$1 AND id=$2 FOR UPDATE")
        .bind(tenant).bind(id).fetch_optional(&mut **tx).await?.ok_or(Error::NotFound)?;
    if version != revision(expected)? {
        return Err(Error::ConfigConflict);
    }
    Ok(row)
}
pub async fn apply(pool: &PgPool, who: &Human, m: Mutation) -> Result<Value> {
    if !governance::valid_text(&m.reason, 500) {
        return Err(Error::Invalid("change reason required"));
    }
    let (read, write) = match m.change {
        Change::FxPublish { .. } => (Permission::FxRead, Permission::FxWrite),
        Change::GuardrailPublish { .. } | Change::PolicyPut { .. } => {
            (Permission::GovernanceRead, Permission::GovernanceWrite)
        }
        _ => (Permission::KeysRead, Permission::KeysWrite),
    };
    let mut tx = begin(pool, who, read, Some(write)).await?;
    // Tenant lock serializes publication, accounting, and duplicate mutations across replicas.
    let hash = governance::digest(
        &serde_json::to_value(&m).map_err(|_| Error::Invalid("invalid mutation"))?,
    )?;
    let previous:Option<(Vec<u8>,Value)>=sqlx::query_as("SELECT body_hash,response FROM settings_mutations WHERE tenant_id=$1 AND user_id=$2 AND operation_id=$3")
        .bind(who.tenant_id).bind(who.id).bind(m.operation_id).fetch_optional(&mut *tx).await?;
    if let Some((old, response)) = previous {
        if old != hash {
            return Err(Error::Conflict);
        }
        return finish(tx, who, response).await;
    }
    let (action, object, version, before, after) = match &m.change {
        Change::GuardrailPublish { .. } | Change::PolicyPut { .. } => {
            crate::governance_settings::apply_locked(&mut tx, who, &m.change).await?
        }
        Change::KeyCreate {
            name,
            key_hash,
            key_prefix,
            budget_cny,
            models,
            expires_at,
        } => {
            let budget =
                validate_key(&mut tx, who, name, budget_cny, models, Some(*expires_at)).await?;
            if key_hash.len() != 64
                || !key_hash
                    .bytes()
                    .all(|c| c.is_ascii_digit() || (b'a'..=b'f').contains(&c))
                || key_prefix.len() != 14
                || !key_prefix.starts_with("sk_br_")
                || !key_prefix[6..]
                    .bytes()
                    .all(|c| c.is_ascii_digit() || (b'a'..=b'f').contains(&c))
            {
                return Err(Error::Invalid("invalid key digest or prefix"));
            }
            let digest: Vec<u8> = (0..64)
                .step_by(2)
                .map(|i| u8::from_str_radix(&key_hash[i..i + 2], 16).expect("validated hex"))
                .collect();
            let id = Uuid::new_v4();
            let inserted=sqlx::query("INSERT INTO virtual_keys(id,tenant_id,name,key_hash,key_prefix,budget_micros,expires_at) VALUES($1,$2,$3,$4,$5,$6,$7) ON CONFLICT DO NOTHING")
                .bind(id).bind(who.tenant_id).bind(name).bind(digest).bind(key_prefix).bind(budget).bind(expires_at).execute(&mut *tx).await?;
            if inserted.rows_affected() != 1 {
                return Err(Error::ConfigConflict);
            }
            replace_grants(&mut tx, who.tenant_id, id, models).await?;
            let v: i64 = sqlx::query_scalar(
                "SELECT config_revision FROM virtual_keys WHERE tenant_id=$1 AND id=$2",
            )
            .bind(who.tenant_id)
            .bind(id)
            .fetch_one(&mut *tx)
            .await?;
            (
                "settings.key_created",
                id.to_string(),
                v,
                Value::Null,
                json!({"name":name,"budget_cny":budget_cny,"expires_at":expires_at,"models":models}),
            )
        }
        Change::KeyUpdate {
            id,
            expected_revision,
            name,
            budget_cny,
            models,
            expires_at,
        } => {
            let budget = validate_key(&mut tx, who, name, budget_cny, models, *expires_at).await?;
            let mut before = key_before(&mut tx, who.tenant_id, *id, expected_revision).await?;
            if !before["revoked_at"].is_null() {
                return Err(Error::ConfigConflict);
            }
            // New keys require expiry. Existing unlimited keys can retain, but cannot remove an expiry.
            if expires_at.is_none() && !before["expires_at"].is_null() {
                return Err(Error::Invalid("cannot remove key expiry"));
            }
            let grants:Vec<String>=sqlx::query_scalar("SELECT model_id FROM key_models WHERE tenant_id=$1 AND key_id=$2 ORDER BY model_id LIMIT 101").bind(who.tenant_id).bind(id).fetch_all(&mut *tx).await?;
            if grants.len() > 100 {
                return Err(Error::Invalid("legacy key requires operator migration"));
            }
            before["models"] = json!(grants);
            let updated=sqlx::query("UPDATE virtual_keys SET name=$3,budget_micros=$4,expires_at=$5 WHERE tenant_id=$1 AND id=$2 AND spent_micros::numeric+reserved_micros::numeric<=$4::numeric")
                .bind(who.tenant_id).bind(id).bind(name).bind(budget).bind(expires_at).execute(&mut *tx).await?;
            if updated.rows_affected() != 1 {
                return Err(Error::ConfigConflict);
            }
            replace_grants(&mut tx, who.tenant_id, *id, models).await?;
            let v: i64 = sqlx::query_scalar(
                "SELECT config_revision FROM virtual_keys WHERE tenant_id=$1 AND id=$2",
            )
            .bind(who.tenant_id)
            .bind(id)
            .fetch_one(&mut *tx)
            .await?;
            (
                "settings.key_updated",
                id.to_string(),
                v,
                before,
                json!({"name":name,"budget_cny":budget_cny,"expires_at":expires_at,"models":models}),
            )
        }
        Change::KeyRevoke {
            id,
            expected_revision,
        } => {
            let before = key_before(&mut tx, who.tenant_id, *id, expected_revision).await?;
            if !before["revoked_at"].is_null() {
                return Err(Error::ConfigConflict);
            }
            let (v,at):(i64,DateTime<Utc>)=sqlx::query_as("UPDATE virtual_keys SET revoked_at=clock_timestamp() WHERE tenant_id=$1 AND id=$2 RETURNING config_revision,revoked_at").bind(who.tenant_id).bind(id).fetch_one(&mut *tx).await?;
            (
                "settings.key_revoked",
                id.to_string(),
                v,
                before,
                json!({"revoked_at":at}),
            )
        }
        Change::FxPublish {
            expected_latest_id,
            usd_cny,
            source,
            effective_at,
        } => {
            text(source)?;
            let rate = money::nonnegative(usd_cny)?;
            if rate <= 0.into() || rate > 1_000_000.into() || rate.scale() > 10 {
                return Err(Error::Invalid("invalid USD/CNY rate"));
            }
            let latest: Option<i64> =
                sqlx::query_scalar("SELECT max(id) FROM fx_rates WHERE tenant_id=$1")
                    .bind(who.tenant_id)
                    .fetch_one(&mut *tx)
                    .await?;
            if latest != expected_latest_id.as_deref().map(revision).transpose()? {
                return Err(Error::ConfigConflict);
            }
            let now: DateTime<Utc> = sqlx::query_scalar("SELECT clock_timestamp()")
                .fetch_one(&mut *tx)
                .await?;
            let effective = effective_at.unwrap_or(now);
            if effective.timestamp_subsec_nanos() % 1000 != 0 {
                return Err(Error::Invalid(
                    "effective time supports at most microsecond precision",
                ));
            }
            if effective < now || effective > now + chrono::Duration::days(366) {
                return Err(Error::Invalid(
                    "effective time must be now or in next 366 days",
                ));
            }
            let v:Option<i64>=sqlx::query_scalar("INSERT INTO fx_rates(tenant_id,usd_cny,source,effective_at) VALUES($1,$2,$3,$4) ON CONFLICT DO NOTHING RETURNING id")
                .bind(who.tenant_id).bind(rate).bind(source).bind(effective).fetch_optional(&mut *tx).await?;
            let v = v.ok_or(Error::ConfigConflict)?;
            (
                "settings.fx_published",
                v.to_string(),
                v,
                json!({"latest_id":latest.map(|n|n.to_string())}),
                json!({"usd_cny":rate.to_string(),"source":source,"effective_at":effective}),
            )
        }
    };
    let response =
        json!({"operation_id":m.operation_id,"object_id":object,"revision":version.to_string()});
    // No secret, digest or prefix is stored in audit / receipt; only a request digest for idempotency.
    sqlx::query("INSERT INTO audit_events(tenant_id,action,object_id,details) VALUES($1,$2,$3,$4)")
        .bind(who.tenant_id).bind(action).bind(&object).bind(json!({"actor":"human_settings","user_id":who.id,"operation_id":m.operation_id,"reason":m.reason,"revision":version.to_string(),"before":before,"after":after})).execute(&mut *tx).await?;
    sqlx::query("INSERT INTO settings_mutations(tenant_id,user_id,operation_id,body_hash,response) VALUES($1,$2,$3,$4,$5)")
        .bind(who.tenant_id).bind(who.id).bind(m.operation_id).bind(hash).bind(&response).execute(&mut *tx).await?;
    finish(tx, who, response).await
}
